const staticData = $getWorkflowStaticData('global');
const inputJson  = $input.first()?.json ?? {};
const msg        = inputJson?.message ?? {};
const chatId     = msg?.chat?.id?.toString() ?? null;
const msgText    = (msg?.text ?? '').trim();
const firstName  = msg?.from?.first_name ?? 'amigo';

// Guard: mensaje inválido
if (!chatId) {
  return [{ json: {
    chatId: 'unknown', firstName: 'amigo', msgText: '',
    session: { ocasion: null, region: null, personas: null, preparacion: null },
    skipNLP: true,
    nextQuestion: '⚠️ Mensaje inválido. Por favor envía un mensaje de texto.',
    groqBody: null
  }}];
}

if (!staticData.sessions) staticData.sessions = {};

// Comandos de reset
const RESET_COMMANDS = ['/start', '/reset', '/nuevo', '/iniciar', '/reiniciar'];
const isReset = RESET_COMMANDS.includes(msgText.toLowerCase());

// Sesión nueva o reset → devolver bienvenida sin llamar a Groq
if (isReset || !staticData.sessions[chatId]) {
  staticData.sessions[chatId] = { ocasion: null, region: null, personas: null, preparacion: null };
  const welcome =
    '👋 ¡Hola ' + firstName + '! Soy *Chef Friko* 🍗, tu asistente culinario oficial de Friko.\n\n' +
    '¡Te ayudaré a encontrar el producto perfecto y una receta deliciosa!\n\n' +
    '🍽️ *¿Para qué ocasión estás cocinando?*\n' +
    '_(Ej: almuerzo familiar, parrillada con amigos, cena rápida, lonchera infantil)_\n\n' +
    '_Puedes responder paso a paso o enviarme toda la info en un solo mensaje, por ejemplo:_\n' +
    '_"cena para 6 personas en Medellín, voy a hacer parrilla"_';
  return [{ json: {
    chatId, firstName, msgText,
    session: staticData.sessions[chatId],
    skipNLP: true,
    nextQuestion: welcome,
    groqBody: null
  }}];
}

const session = staticData.sessions[chatId];

// Construir prompt para Groq NLP Extractor
const systemPrompt = [
  'Eres un extractor de datos para un bot culinario colombiano.',
  'Analiza el mensaje del usuario y extrae exactamente estos 4 campos en JSON.',
  '',
  'CAMPOS A EXTRAER:',
  '- ocasion: La ocasion de cocina (string o null). Ej: "almuerzo familiar", "parrillada", "cena romantica", "evento empresarial".',
  '- region: Ciudad o region de Colombia (string o null). Ej: "Antioquia", "Bogota", "Medellin", "Atlantico", "Santander", "Costa Caribe".',
  '- personas: Numero de personas (entero positivo o null). Convierte: "tres"=3, "dos"=2, "una docena"=12, "para mi solo"=1, "para mi"=1.',
  '- preparacion: Tipo de preparacion (string o null). Ej: "horno", "sarten", "parrilla", "airfryer", "freidora", "olla a presion", "cualquiera".',
  '',
  'REGLAS ESTRICTAS:',
  '- Responde SOLO con JSON valido. Sin markdown, sin explicaciones, sin texto extra.',
  '- Si un campo no aparece claramente en el mensaje, devuelve null para ese campo.',
  '- personas DEBE ser un numero entero positivo o null, NUNCA un string.',
  '- No inventes datos que no esten en el mensaje.',
  '',
  'EJEMPLOS:',
  'Input: "cena para tres personas en Medellin"',
  'Output: {"ocasion":"cena","region":"Medellin","personas":3,"preparacion":null}',
  '',
  'Input: "almuerzo familiar en Bogota para 8, lo voy a hacer al horno"',
  'Output: {"ocasion":"almuerzo familiar","region":"Bogota","personas":8,"preparacion":"horno"}',
  '',
  'Input: "parrillada"',
  'Output: {"ocasion":"parrillada","region":null,"personas":null,"preparacion":"parrilla"}'
].join('\n');

const groqBody = {
  model: 'llama-3.3-70b-versatile',
  temperature: 0,
  max_tokens: 200,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user',   content: msgText }
  ]
};

return [{ json: { chatId, firstName, msgText, session, skipNLP: false, nextQuestion: null, groqBody } }];

// Obtener datos de Init Session de forma segura
let initData = {};
try {
  initData = $('Init Session').first()?.json ?? {};
} catch(e) {
  initData = {};
}

const chatId    = initData.chatId    ?? 'unknown';
const firstName = initData.firstName ?? 'amigo';
const msgText   = initData.msgText   ?? '';

// Clonar sesión de forma segura (nunca asumir que existe)
let session = {
  ocasion:     initData.session?.ocasion     ?? null,
  region:      initData.session?.region      ?? null,
  personas:    initData.session?.personas    ?? null,
  preparacion: initData.session?.preparacion ?? null
};

// Parsear respuesta de Groq de forma segura
const groqRaw = $input.first()?.json ?? {};
let extracted = { ocasion: null, region: null, personas: null, preparacion: null };

try {
  const rawContent = groqRaw?.choices?.[0]?.message?.content ?? '{}';
  // Limpiar posibles backticks de markdown
  const cleaned    = rawContent.replace(/```json|```/gi, '').trim();
  const parsed     = JSON.parse(cleaned);

  // Validar y limpiar cada campo extraído
  if (typeof parsed?.ocasion === 'string' && parsed.ocasion.trim().length > 1) {
    extracted.ocasion = parsed.ocasion.trim();
  }
  if (typeof parsed?.region === 'string' && parsed.region.trim().length > 1) {
    extracted.region = parsed.region.trim();
  }
  if (typeof parsed?.personas === 'number' && Number.isInteger(parsed.personas) &&
      parsed.personas > 0 && parsed.personas <= 1000) {
    extracted.personas = parsed.personas;
  }
  if (typeof parsed?.preparacion === 'string' && parsed.preparacion.trim().length > 1) {
    extracted.preparacion = parsed.preparacion.trim();
  }
} catch(e) {
  // Groq falló o devolvió JSON inválido — continuar con nulls
}

// Merge: rellenar campos de sesión sólo si aún están vacíos
if (!session.ocasion     && extracted.ocasion)     session.ocasion     = extracted.ocasion;
if (!session.region      && extracted.region)      session.region      = extracted.region;
if (!session.personas    && extracted.personas)    session.personas    = extracted.personas;
if (!session.preparacion && extracted.preparacion) session.preparacion = extracted.preparacion;

// Persistir sesión actualizada
const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
staticData.sessions[chatId] = session;

// Determinar estado y próxima pregunta
const allReady = !!(session.ocasion && session.region && session.personas && session.preparacion);
let step         = allReady ? 'send_to_rag' : 'ask_question';
let nextQuestion = '';

if (!allReady) {
  if (!session.ocasion) {
    nextQuestion =
      '🍽️ *¿Para qué ocasión estás cocinando?*\n' +
      '_(Ej: almuerzo familiar, parrillada con amigos, cena rápida, lonchera infantil, evento especial)_';
  } else if (!session.region) {
    nextQuestion =
      '✅ _Ocasión: ' + session.ocasion + '_\n\n' +
      '📍 *¿En qué región de Colombia te encuentras?*\n' +
      '_(Ej: Antioquia, Bogotá, Atlántico, Santander, Eje Cafetero, Costa Caribe)_';
  } else if (!session.personas) {
    nextQuestion =
      '✅ _Región: ' + session.region + '_\n\n' +
      '👥 *¿Para cuántas personas vas a cocinar?*\n' +
      '_(Solo el número, ejemplo: 4)_';
  } else {
    nextQuestion =
      '✅ _Para ' + session.personas + ' personas_\n\n' +
      '🍳 *¿Tipo de preparación preferida?*\n' +
      '_(Ej: horno, sartén, parrilla, airfryer, freidora de aire, olla a presión)_\n\n' +
      '_Si no tienes preferencia escribe: cualquiera_';
  }
}

return [{ json: { chatId, firstName, session, step, nextQuestion } }];

// Obtener datos con fallbacks seguros
const data      = $input.first()?.json ?? {};
const chatId    = data.chatId    ?? 'unknown';
const firstName = data.firstName ?? 'amigo';
const session   = data.session   ?? {};

const ocasion     = session.ocasion     ?? 'no especificada';
const region      = session.region      ?? 'no especificada';
const personas    = session.personas    ?? 1;
const preparacion = session.preparacion ?? 'cualquiera';

const prompt = [
  'Hola Chef Friko, necesito tu ayuda para esta situación:',
  '',
  '📌 Ocasión: ' + ocasion,
  '📍 Región de Colombia: ' + region,
  '👥 Número de personas: ' + personas,
  '🍳 Tipo de preparación preferida: ' + preparacion,
  '',
  'Por favor recomiéndame:',
  '1. El mejor producto Friko del catálogo para esta situación con justificación',
  '2. Una receta completa paso a paso ajustada para exactamente ' + personas + ' persona(s)',
  '3. Tips adicionales de preparación',
  '',
  '¡Muchas gracias!'
].join('\n');

return [{ json: {
  chatId,
  firstName,
  session,
  flowisePayload: {
    question:  prompt,
    sessionId: 'telegram_' + chatId
  }
}}];

const httpResponse = $input.first()?.json ?? {};

// Obtener chatId/firstName del nodo upstream de forma segura
let chatId    = 'unknown';
let firstName = 'amigo';

try {
  const buildData = $('Build Flowise Query').first()?.json ?? {};
  chatId    = buildData.chatId    ?? 'unknown';
  firstName = buildData.firstName ?? 'amigo';
} catch(e) {
  // Nodo no encontrado — continuar con defaults
}

// Parsear respuesta de Flowise
const rawText   = (httpResponse?.text   ?? '').trim();
const rawAnswer = (httpResponse?.answer ?? '').trim();
const hasError  = !!(httpResponse?.error) || (!rawText && !rawAnswer);

let success      = false;
let responseText = '';

if (hasError) {
  responseText = [
    '😔 Tuve un inconveniente al consultar el catálogo de Friko.',
    '',
    'Por favor intenta de nuevo escribiendo /nuevo.',
    '_Si el problema persiste, intenta más tarde._'
  ].join('\n');
} else {
  success = true;
  responseText =
    (rawText || rawAnswer) +
    '\n\n─────────────────\n' +
    '💬 _¿Quieres otra recomendación?_ Escribe /nuevo\n' +
    '🌐 Más recetas en www.momentosfriko.com';
}

// Limpiar sesión del usuario tras responder
try {
  const staticData = $getWorkflowStaticData('global');
  if (staticData?.sessions && chatId !== 'unknown') {
    delete staticData.sessions[chatId];
  }
} catch(e) { /* ignorar */ }

return [{ json: { chatId, firstName, responseText, success } }];
